185	// When the input stream fails after whole lines, everything already read is
186	// processed in order and flushed; the read error is reported wrapped with
187	// ErrLogRead, the failure count covers only genuinely invalid complete
188	// lines, and an unterminated fragment delivered with the failure is neither
189	// normalized, counted, nor emitted.
190	func TestNormalizeIOReadErrorAfterCompleteLines(t *testing.T) {
191		complete := validLog("a") + "\n" +
192			`{"timestamp":"not-a-time","action":"b"}` + "\n" +
193			validLog("c") + "\n"
194		cases := []struct {
195			name     string
196			fragment []byte
197		}{
198			{"error carries an unterminated fragment", []byte(`{"timestamp":"FRAGMENT-MARKER","action":`)},
199			{"error stands alone after a newline", nil},
200			{"error carries only blank bytes", []byte("   ")},
201		}
202		for _, tc := range cases {
203			t.Run(tc.name, func(t *testing.T) {
204				src := &scriptReader{steps: []scriptStep{
205					{data: []byte(complete)},
206					{data: tc.fragment, err: errSimulatedRead},
207				}}
208				var out bytes.Buffer
209				failures, err := NormalizeReader(src, &out)
210				if err == nil {
211					t.Fatalf("read failure must be returned, not treated as success")
212				}
213				if !errors.Is(err, ErrLogRead) {
214					t.Fatalf("error must match ErrLogRead, got %v", err)
215				}
216				if !errors.Is(err, errSimulatedRead) {
217					t.Fatalf("underlying read cause must stay reachable, got %v", err)
218				}
219				if errors.Is(err, ErrLogWrite) {
220					t.Fatalf("a healthy writer must not tag the error as a write failure: %v", err)
221				}
222				if !strings.Contains(err.Error(), errSimulatedRead.Error()) {
223					t.Fatalf("error text must stay recognizable as the read cause, got %q", err.Error())
224				}
225				if failures != 1 {
226					t.Fatalf("read fault must not count as a log; only the one bad line counts, got %d", failures)
227				}
228				results := decodeResults(t, out.Bytes())
229				if len(results) != 3 {
230					t.Fatalf("only the 3 complete lines may be emitted, got %#v", results)
231				}
232				if results[0]["line"] != float64(1) || results[0]["ok"] != true ||
233					results[1]["line"] != float64(2) || results[1]["ok"] != false ||
234					results[2]["line"] != float64(3) || results[2]["ok"] != true {
235					t.Fatalf("processed lines must keep order, numbers and outcomes: %#v", results)
236				}
237				if msg, _ := results[1]["error"].(string); !strings.Contains(msg, FieldTimestamp) {
238					t.Fatalf("per-line error explanation must be preserved, got %q", msg)
239				}
240				if bytes.Contains(out.Bytes(), []byte("FRAGMENT-MARKER")) {
241					t.Fatalf("unterminated fragment must not produce an event or line error: %q", out.String())
242				}
243			})
244		}
245	}
