1	package relayproof
2	
3	// Regression coverage for read interruptions while the 192.0.2.0/24 source
4	// filter is active. The filter must not blur the line between a stream that
5	// simply had no admitted events and one that was cut off before it was fully
6	// read:
7	//
8	//   - Complete lines already delivered by a failed read keep their results,
9	//     in physical line order: admitted successes are emitted, out-of-network
10	//     successes and blank lines stay invisible without renumbering anything,
11	//     and a failed line is still emitted with its physical number and reason
12	//     even though its source is outside the network.
13	//   - A newline-less tail delivered together with a non-EOF read fault is part
14	//     of the failed read: whether it is a complete, admittable JSON object or
15	//     carries an invalid timestamp, it produces no success or failure record
16	//     and does not move the failure count.
17	//   - The caller still receives the interruption as ErrLogRead wrapping the
18	//     underlying cause, even when output is empty and the failure count is
19	//     zero. The same bytes at a clean EOF are ordinary completion instead.
20	//
21	// Every scenario is scripted through scriptReader from normalize_io_test.go,
22	// so the boundary reproduces deterministically offline without real pipes,
23	// networks, or device failures.
24	
25	import (
26		"bytes"
27		"errors"
28		"io"
29		"strings"
30		"testing"
31	)
32	
33	// filteredInterruptFixture builds the shared batch:
34	//
35	//	line 1: valid log from inside 192.0.2.0/24      -> admitted success
36	//	line 2: valid log from outside the network      -> silently filtered
37	//	line 3: blank line                              -> no output, keeps number
38	//	line 4: outside source, invalid timestamp       -> failure with reason
39	//
40	// All four end with "\n". The returned tail fragments have NO trailing
41	// newline: at a clean EOF they are a fifth physical line, under a read fault
42	// they are a fragment of the failed read.
43	func filteredInterruptFixture(t *testing.T) (filter *SourceCIDRFilter, complete string) {
44		t.Helper()
45		f, err := ParseSourceCIDRFilter("192.0.2.0/24")
46		if err != nil {
47			t.Fatal(err)
48		}
