	}
	if errors.Is(err, ErrLogWrite) || errors.Is(err, errSimulatedWrite) {
		t.Fatalf("the later flush fault must not replace or shadow the read cause: %v", err)
	}
	msg := err.Error()
	if !strings.Contains(msg, errSimulatedRead.Error()) {
